const ExcelJS = require('exceljs');
(async () => {
  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet('Invoice');
  ws.columns = [
    { header: 'Field', key: 'field', width: 20 },
    { header: 'Value', key: 'value', width: 25 },
  ];
  ws.getRow(1).font = { bold: true };
  ws.addRow({ field: 'Invoice #', value: '1042' });
  ws.addRow({ field: 'Date', value: '2026-08-01' });
  ws.addRow({ field: 'Total', value: '$2500.00' });
  await wb.xlsx.writeFile('invoice.xlsx');
  console.log('Created invoice.xlsx');
})();
```

Then run:
```bash
npm install exceljs
node create_invoice.js
```

